from paths_repl import *

def n(v):return f"{v:.2f}".replace(".",",")

def main():
    res=get(D/"results.json");panel=get(D/"panel.json");reads=get(D/"read-overlap-summary.json")
    ctx=get(D/"contexts.json.gz");seal=get(D/"answer-seal.json");cost=get(D/"costs.json")
    groups=res["groups"];all_=groups["all"];PCT=100
    def diff(group,pair,j):
        c=groups[group]["contrasts"][pair];lo,hi=c["cluster_ci"][j]
        return f'{n(c["pp"][j])} [{n(lo)}; {n(hi)}]'
    lab={"true":"Подлинное упоминание","lex":"Лексическое расширение","sham":"Переназначение 47011"}
    txt=["# Независимая панель 2WikiMultiHopQA и проверка вторых чтений","",
      f'На 640 заранее выбранных вопросах из официального train Answer F1 Qwen достиг **{n(PCT*all_["means"]["true"][1])}** с подлинным переходом и **{n(PCT*all_["means"]["lex"][1])}** с лексическим расширением. Первичный парный эффект **{diff("all","true-lex",1)} п.п.** Эффект относительно единственной закреплённой подмены **{diff("all","true-sham",1)} п.п.** Для интервалов 95% выполнено 10 000 парных перевыборок 640 разных первых документов. [Заранее закреплённый протокол](./PROTOCOL_RU.md) · [Числа](./results.json)',"",
      "| Второе чтение | EM, % | Answer F1 | Найдены все опорные заголовки, % | Средняя доля найденных опор, % | Строка ответа в доставленном тексте, % |","|---|---:|---:|---:|---:|---:|"]
    for tag,title in lab.items():
        j="sham47011" if tag=="sham" else tag
        em,ff,full,present=all_["means"][tag]
        txt.append("| "+title+" | "+" | ".join(n(v*100) for v in [em,ff,full,res["mean_doc_recall"][j],present])+" |")
    s=groups["switched"];p=all_["contrasts"]["true-lex"];lo=min(row["refs"]["true"][2] for row in ctx.values());hi=max(row["refs"]["true"][2] for row in ctx.values())
    txt+=["",f'Настоящее упоминание сменило второго адресата в {s["n"]}/640 случаях ({n(100*s["n"]/640)}%). На этих вопросах true–lex составил {diff("switched","true-lex",1)} п.п. F1, true–placebo — {diff("switched","true-sham",1)}. На остальных вопросах ({groups["same"]["n"]}) все три входа и результата совпали. Изменение EM на всей панели составило {diff("all","true-lex",0)} п.п. Относительно лексического контроля F1 вырос на {p["wins"][1]} вопросах, упал на {p["losses"][1]} и остался прежним на {640-p["wins"][1]-p["losses"][1]}. Подмена минус лексический контроль — {diff("all","sham-lex",1)} п.п. Состав переназначений, число упоминаний, их позиции и фактически выбранный второй документ в каждой из трёх ветвей проверяются для каждого вопроса. [Адреса](./orders.json.gz) · [Исходы](./outcomes.json.gz)',"",
      "### Независимость вопросов и пересечения документов","",
      f'R32 ранее прошёл все 12 576 вопросов dev. Для репликации использовано другое разбиение того же корпуса. Из {panel["source_n"]:,} строк train рассмотрены первые {panel["examined"]} по хешу до набора 640. Отклонено 80 ранее встречавшихся первых документов и два повторных первых документа внутри панели. Все ID и полные нормализованные вопросы отличаются от известных вопросов 2Wiki dev, HotpotQA validation и MuSiQue train/dev. Каждый из 640 первых документов отличается от всех абзацев этих каталогов по точной паре заголовок+текст. Авторский архив с Wikidata ID и parquet содержат одинаковые вопросы, заголовки и предложения во всех выбранных строках. [Панель и знаменатели](./panel.json)',"",
      f'В {panel["pooled_catalogs_sharing"]} из 640 полных каталогов встречались другие абзацы из прежних массивов. Среди выбранных вторых документов это произошло у {reads["historical_second"]["true"]} вопросов в true, {reads["historical_second"]["lex"]} в lexical и {reads["historical_second"]["sham47011"]} в placebo. В {reads["all_new_inputs"]} вопросах каждый фактически выбранный в трёх ветвях документ отличался от всего старого каталога. Аудит проверяет точное совпадение, поэтому близкий пересказ мог остаться. Происхождение корпуса и публичный train допускают попадание материала в предобучение Qwen. [Пересечение выбранных чтений](./read-overlap-summary.json)',"",
      f'Общий для каждого вопроса размер второго фрагмента определяли все пять прежних placebo и четыре базовые политики. Оценена одна перестановка 47011, тогда как основная dev-панель усредняла пять. Каждый вопрос получил два фрагмента. Длина всего токенизированного запроса оказалась одинаковой во всех трёх условиях, в среднем {n(res["input_mean"])} токена, от {lo} до {hi}. Из 1 920 логических назначений возникли {seal["unique"]} уникальных запросов и 32 повтора, с {seal["different"]} расхождениями. Длительность генерации вместе с повторами составила {n(seal["seconds"])} с. Сервер вернул {cost["events"]} записей времени и {cost["input_truncations"]} усечений входа. [Квитанции](./answer-seal.json) · [Затраты](./costs.json)',"",
      f'Официальный v1.1 EM/F1 использовал альтернативные наименования и демонимы. В {res["alias_extended_questions"]} вопросах золотой набор включал больше одной строки. Независимый скрипт проверяет все 1 920 баллов и покрытие опорных заголовков. Это тест Qwen3-4B-Instruct-2507 Q4_K_M в режиме двух чтений из предоставленного каталога. [Авторский оценщик](https://github.com/Alab-NII/2wikimultihop/blob/13800e5be57df1b4040b9b1588c6c811779e69e9/2wikimultihop_evaluate_v1.1.py) · [Воспроизведение](./REPRODUCE_RU.md)']
    (D/"REPORT_RU.md").write_bytes(("\n".join(txt)+"\n").encode())
if __name__=="__main__":main()
